import copy
import re

from .clue_agents import ClueBoard, known
from .clue_colony import COLONY_OPTS

FIX = ('ask', 'table', 'record', 'check')
FIX_RULES = dict(
    ask="'ask' for the clues you lack on the subtask you have open (target = it): your request shows on the board to "
        "every teammate until you open another subtask or it closes; asking takes your turn.",
    table='The board lists each clue known to the team once per subtask.',
    record="Each shared clue shows how many of its sender's earlier shares were true, counted over subtasks solved so far.",
    check="'check' a clue on the board (target = its subtask, clue = its text): next turn you learn whether it is true; "
          "checking takes your turn.",
    recordPrivate="Each shared clue shows how many of its sender's earlier shares were true, counted over subtasks you "
                  "solved yourself.",
    checkPublic="'check' a clue on the board (target = its subtask, clue = its text): next turn every teammate and you "
                "learn whether it is true; checking takes your turn.")
_WORD = dict(record='private', check='public')    # Phase 14: the string setting of each option (no aliases)
_RE = re.compile(r'x\s*mod\s*(\d+)\s*=\s*(-?\d+)', re.I)


def fixOptions(world):
    "The options set in a cfg.world, as TextClueEnv keywords (absent: off; Phase 18's colony options and q included)."
    return {k: world[k] for k in FIX + COLONY_OPTS + ('q',) if k in world}


def fixSettings(record, check):
    "record (False, True: public, 'private') and check (False, True: private, 'public') as stored; anything else fails."
    out = tuple(v if v == _WORD[k] else bool(v) for k, v in (('record', record), ('check', check)))
    if any(isinstance(v, str) and v != _WORD[k] for k, v in zip(('record', 'check'), (record, check))):
        raise ValueError(f'record must be False, True or {_WORD["record"]!r}; check False, True or {_WORD["check"]!r}')
    return out


def fixChecked(env, i):
    "The checks agent i's known clues apply: none (check off), its own (Phase 13) or every agent's (check 'public')."
    return env.checkedAll if env.check == 'public' else env.checked.get(i, {}) if env.check else None


def fixSchema(schema, ask=False, check=False):
    "The schema itself with both actions off (Phase 11 requests unchanged); else a copy whose action enum adds them."
    if not (ask or check):
        return schema
    s = copy.deepcopy(schema)
    s['properties']['action']['enum'] += ['ask'] * bool(ask) + ['check'] * bool(check)
    return s


def trackRecord(a, board, viewer=None):
    """(true, checked) over agent a's shares of the subtasks solved so far (a solved subtask's clues are known); with
    `viewer`, only those of the subtasks the viewer solved itself (the private record)."""
    ok = (lambda sb: sb >= 0) if viewer is None else (lambda sb: sb == viewer)
    s = [not x[6] for x in board.shareLog if x[1] == a and ok(board.tasks[x[2]].solvedBy)]
    return sum(s), len(s)


def _list(xs, word):
    xs = [f"'{x}'" for x in xs]
    return ', '.join(xs[:-1]) + f' {word} ' + xs[-1] if len(xs) > 1 else xs[0]


def fixRules(env, text):
    "The rules with the options' sentences after the channel paragraph and the new actions in the reply format."
    on, new = [k for k in FIX if getattr(env, k)], [k for k in ('ask', 'check') if getattr(env, k)]
    if not on:
        return text
    rule = lambda k: FIX_RULES[dict(record='recordPrivate', check='checkPublic')[k] if getattr(env, k) == _WORD.get(k) else k]
    text = text.replace('did not see it.\n\n', 'did not see it.\n\n' + ' '.join(rule(k) for k in on) + '\n\n', 1)
    if new:
        text = text.replace("action is 'open', 'submit', 'share' or 'wait'",
                            'action is ' + _list(['open', 'submit', 'share', 'wait'] + new, 'or'))
        text = text.replace("subtask name for 'open' and 'share'", 'subtask name for ' + _list(['open', 'share'] + new, 'and'))
        text = text.replace("clue text for 'share' (", 'clue text for ' + _list(['share'] + ['check'] * bool(env.check), 'and') + ' (')
    return text


def fixBoard(env, t, view, i=None):
    """The board line with `table` (each distinct clue once per subtask, no sender) or `record` (senders' track records;
    with record 'private', counted over the subtasks the viewing agent i solved)."""
    if env.table:
        return 'Known to the team: ' + ('; '.join(f'T{k}: ' + ', '.join(dict.fromkeys(
            f'x mod {p} = {r}' for _, p, r, _, _ in sorted(xs, key=lambda x: x[4]))) for k, xs in view.items()) or 'none')
    v = i if env.record == 'private' else None
    rec = {a: trackRecord(a, env.world, v) for a in {x[3] for xs in view.values() for x in xs}}
    tr = lambda a: f'record {rec[a][0]}/{rec[a][1]} true' if rec[a][1] else 'record none'
    return 'Clues shared on the board: ' + ('; '.join(f'T{k}: x mod {p} = {r} (agent {a}, {t - ts:g} turns ago, {tr(a)})'
                                                      for k, xs in view.items() for _, p, r, a, ts in xs) or 'none')


def fixLines(env, i, t, channel):
    """Observation lines of the options: the live requests (`ask`), the result of the agent's last check (`check`) and,
    with check 'public', the teammates' checks since its last turn."""
    b, out, mine = env.world, [], env._known.get(i, {})
    if env.ask and isinstance(channel, ClueBoard):
        def lack(k, a):
            theirs = known(a, b, channel, fixChecked(env, a))[k]
            return sum(j not in theirs for j in mine.get(k, {}))
        out.append('Requests: ' + ('; '.join(f'agent {a} needs clues for T{k} (you hold {lack(k, a)})'
                                             for k, a, _ in channel.requests(b)) or 'none'))
    if i in env._checks:
        out.append(env._checks.pop(i))
    return out + env._told.pop(i, [])


def fixParse(env, parsed, i, a, k):
    """'ask' (target = the agent's open subtask, still open) and 'check' (target open, clue = a clue posted for it on
    the board) -> a wait on the board, with report ('ask', k) for an ask; anything else invalid. A public check's result
    goes to the shared checks and to every teammate's next observation."""
    b, ch, wait = env.world, env._chan, ('wait', None)
    if not isinstance(ch, ClueBoard) or k not in b.open:
        return wait, None, False
    if a == 'ask' and env.ask and b.opened[i] == k:
        env._did[i] = f'asked for clues for T{k}'
        return wait, ('ask', k), True
    m = _RE.search(str(parsed.get('clue', '')))
    posts = sorted((x for x in ch.posts.get(k, []) if m and (x[1], x[2]) == (int(m.group(1)), int(m.group(2)))),
                   key=lambda x: x[4])
    if a == 'check' and env.check and posts:
        j, p, r, src, _ = posts[0]                     # the sender shown is the clue's first poster
        ok = b.tasks[k].task.clue(j)[1] == r
        res = f"T{k} x mod {p} = {r} (from agent {src}) is {'true' if ok else 'false'}."
        if env.check == 'public':
            env.checkedAll[(k, j, r)] = ok
            for a2 in range(b.nAgents):
                if a2 != i:
                    env._told.setdefault(a2, []).append(f'Checked by agent {i}: {res}')
        else:
            env.checked.setdefault(i, {})[(k, j, r)] = ok
        env._checks[i] = f'Your check: {res}'
        env._did[i] = f'checked T{k}: x mod {p} = {r}'
        return wait, None, True
    return wait, None, False
